/**
 * Extra clinic formulary — WHO EML, top US fills, hospital / oncology staples
 * not already on the teaching core. Empty enzyme lists mean no CYP story on
 * this desk, not 'safe.' Teaching. Not a dose. The PI governs.
 */

import type { Drug, Enzyme, EnzymeRole, PdFlag, Strength, SubstrateSensitivity } from "./types";

type Row = [string, string, string[], string, string, PdFlag[], string, string[]];

function sub(enzyme: Enzyme, sensitivity: SubstrateSensitivity, pathway: "clearance" | "activation" = "clearance", nti = false): EnzymeRole {
  return { enzyme, kind: "substrate", sensitivity, pathway, nti };
}
function inh(enzyme: Enzyme, strength: Strength): EnzymeRole {
  return { enzyme, kind: "inhibitor", strength };
}
function ind(enzyme: Enzyme, strength: Strength): EnzymeRole {
  return { enzyme, kind: "inducer", strength };
}

function enz(s: string): EnzymeRole[] {
  if (!s) return [];
  return s.split(";").map((part) => {
    const [k, e, v] = part.split(":") as [string, Enzyme, string];
    if (k === "s") return sub(e, v as SubstrateSensitivity);
    if (k === "sa") return sub(e, v as SubstrateSensitivity, "activation");
    if (k === "sn") return sub(e, v as SubstrateSensitivity, "clearance", true);
    if (k === "i") return inh(e, v as Strength);
    return ind(e, v as Strength);
  });
}

function row(r: Row): Drug {
  const [id, name, brands, cls, e, pd, toxicityHint, aliases] = r;
  return { id, name, brands, cls, aliases, enzymes: enz(e), pd, toxicityHint, kind: "drug" };
}

